// Datas de referencia (UTC, meia-noite)
const hoje = new Date();
hoje.setUTCHours(0,0,0,0);
const ontem = new Date(hoje);
ontem.setUTCDate(hoje.getUTCDate() - 1);
const inicio7d = new Date(hoje);
inicio7d.setUTCDate(hoje.getUTCDate() - 7);

function toDateOnly(str) {
  return new Date(String(str).slice(0,10) + 'T00:00:00Z');
}

const tipos = ['1', '2', '3', 'outbound'];

// --- MAPA DE MÍDIA DO MAILING (cruza mailing_id com a aba "mailing" da planilha) ---
const MIDIA_REMARKETING = 15;
const MIDIA_INBOUND = 14;

const mailingRows = $('Mailing - Ler Dados').all().map(i => i.json);
const midiaPorMailingId = {};
for (const m of mailingRows) {
  if (m.id === undefined || m.id === null) continue;
  midiaPorMailingId[String(m.id)] = Number(m.midia);
}
function getMidia(mailingId) {
  if (!mailingId) return null;
  return midiaPorMailingId[String(mailingId)];
}

// --- DISPAROS (TOTAL + TIPOS - ambos vindos do sdr_eventos, via node "Tipos de disparo") ---
// A mv_sdr_disparos_diario está desatualizada (não vem sendo refreshada), por isso
// o total e os tipos agora vêm da mesma fonte viva: sdr_eventos.
function extrairTipoDisparo(payload) {
  try {
    const obj = typeof payload === 'string' ? JSON.parse(payload) : payload;
    const template = obj && obj.template;
    if (!template) return null;
    // Disparo inicial de outbound não segue o padrão "mensagem_N_" - é um tipo à parte.
    if (template === 'disparo_inicial_outbound') return 'outbound';
    const match = template.match(/mensagem_(\d+)_/);
    return match ? match[1] : null;
  } catch (e) {
    return null;
  }
}

const eventosTipo = $('Tipos de disparo1').all().map(i => i.json)
  .filter(e => e.tipo_evento === 'disparo_enviado');

const tiposDisparoOntemPorTipo = {};
const tiposDisparo7dPorTipo = {};
for (const tipo of tipos) {
  tiposDisparoOntemPorTipo[tipo] = 0;
  tiposDisparo7dPorTipo[tipo] = 0;
}

let disparosOntemTotal = 0;
let disparos7dTotal = 0;
let disparosOntemRemarketing = 0, disparosOntemInbound = 0;
let disparos7dRemarketing = 0, disparos7dInbound = 0;

for (const e of eventosTipo) {
  if (!e.created_at) continue;
  const criado = new Date(e.created_at);
  const dia = new Date(Date.UTC(criado.getUTCFullYear(), criado.getUTCMonth(), criado.getUTCDate()));
  const tipo = extrairTipoDisparo(e.payload);
  const midia = getMidia(e.mailing_id);

  if (dia.getTime() === ontem.getTime()) {
    disparosOntemTotal += 1;
    if (tipo) tiposDisparoOntemPorTipo[tipo] = (tiposDisparoOntemPorTipo[tipo] || 0) + 1;
    if (midia === MIDIA_REMARKETING) disparosOntemRemarketing++;
    if (midia === MIDIA_INBOUND) disparosOntemInbound++;
  }
  if (dia >= inicio7d && dia < hoje) {
    disparos7dTotal += 1;
    if (tipo) tiposDisparo7dPorTipo[tipo] = (tiposDisparo7dPorTipo[tipo] || 0) + 1;
    if (midia === MIDIA_REMARKETING) disparos7dRemarketing++;
    if (midia === MIDIA_INBOUND) disparos7dInbound++;
  }
}

// --- RESPOSTAS ---
const respostas = $('Respostas - Ler Dados').all().map(i => i.json);
let respostasHoje = 0;
let respostasOntem = 0;
let respostas7d = 0;

for (const r of respostas) {
  const dia = toDateOnly(r.dia);
  const qtd = Number(r.leads_que_responderam) || 0;
  if (dia.getTime() === hoje.getTime()) respostasHoje += qtd;
  if (dia.getTime() === ontem.getTime()) respostasOntem += qtd;
  if (dia >= inicio7d && dia < hoje) respostas7d += qtd;
}

const taxaRespostaOntem = disparosOntemTotal > 0 ? (respostasHoje / disparosOntemTotal * 100) : 0;
const taxaResposta7d = disparos7dTotal > 0 ? (respostas7d / disparos7dTotal * 100) : 0;

// --- RESPOSTAS POR TIPO DE DISPARO ---
// Cruza cada resposta_recebida com o disparo_enviado mais recente do mesmo mailing_id
// (antes do horário da resposta) pra descobrir qual tipo (1/2/3) gerou aquela resposta.
const todosEventos = $('Tipos de disparo1').all().map(i => i.json);

const disparosPorMailing = {};
for (const e of todosEventos) {
  if (e.tipo_evento !== 'disparo_enviado' || !e.mailing_id || !e.created_at) continue;
  const registro = {
    created_at: new Date(e.created_at),
    tipo: extrairTipoDisparo(e.payload)
  };
  if (!disparosPorMailing[e.mailing_id]) disparosPorMailing[e.mailing_id] = [];
  disparosPorMailing[e.mailing_id].push(registro);
}
// garante ordem cronológica pra busca do "mais recente antes da resposta"
for (const mailingId in disparosPorMailing) {
  disparosPorMailing[mailingId].sort((a, b) => a.created_at - b.created_at);
}

function encontrarTipoDoDisparoAnterior(mailingId, dataResposta) {
  const lista = disparosPorMailing[mailingId];
  if (!lista) return null;
  let tipoEncontrado = null;
  for (const d of lista) {
    if (d.created_at <= dataResposta) {
      tipoEncontrado = d.tipo; // sobrescreve até achar o mais recente antes da resposta
    } else {
      break;
    }
  }
  return tipoEncontrado;
}

const respostasTipoHoje = { '1': 0, '2': 0, '3': 0, 'outbound': 0 };
const respostasTipo7d = { '1': 0, '2': 0, '3': 0, 'outbound': 0 };
let respostasSemDisparoHoje = 0;
let respostasSemDisparo7d = 0;
let respostasHojeRemarketing = 0, respostasHojeInbound = 0;
let respostas7dRemarketing = 0, respostas7dInbound = 0;

const vistosHoje = new Set();
const vistos7d = new Set();

for (const e of todosEventos) {
  if (e.tipo_evento !== 'resposta_recebida' || !e.created_at) continue;

  const criado = new Date(e.created_at);
  const dia = new Date(Date.UTC(criado.getUTCFullYear(), criado.getUTCMonth(), criado.getUTCDate()));
  const tipo = e.mailing_id ? encontrarTipoDoDisparoAnterior(e.mailing_id, criado) : null;
  const midia = getMidia(e.mailing_id);
  const chave = `${e.mailing_id}_${dia.getTime()}`; // dedupe: mesmo lead, mesmo dia = 1 resposta

  if (dia.getTime() === hoje.getTime() && !vistosHoje.has(chave)) {
    vistosHoje.add(chave);
    if (tipo) respostasTipoHoje[tipo] = (respostasTipoHoje[tipo] || 0) + 1;
    else respostasSemDisparoHoje++;
    if (midia === MIDIA_REMARKETING) respostasHojeRemarketing++;
    if (midia === MIDIA_INBOUND) respostasHojeInbound++;
  }
  if (dia >= inicio7d && dia < hoje && !vistos7d.has(chave)) {
    vistos7d.add(chave);
    if (tipo) respostasTipo7d[tipo] = (respostasTipo7d[tipo] || 0) + 1;
    else respostasSemDisparo7d++;
    if (midia === MIDIA_REMARKETING) respostas7dRemarketing++;
    if (midia === MIDIA_INBOUND) respostas7dInbound++;
  }
}

// --- MAPA DE NOMES DE MÍDIA (ajuste/complete conforme os códigos reais) ---
const MIDIA_NOMES = {
  '1': 'Outbound Bank',
  '2': 'Parcerias',
  '4': 'Outbound Raul',
  '5': 'Remarketing',
  '14': 'Inbound',
  '15': 'Remarketing',
  // 10, 11, 12, 41 ainda sem nome confirmado — aparecem como "Mídia X" no relatório até confirmar
};
function nomeMidia(codigo) {
  if (codigo === null || codigo === undefined || codigo === '') return 'Sem mídia';
  return MIDIA_NOMES[String(codigo)] || `Mídia ${codigo}`;
}

// --- CALLS MARCADAS (via calls_status_log, to_status = 'grupo_criado') ---
// NOVA LÓGICA: substitui completamente a lógica antiga baseada em sdr_reunioes.atualizado_em
// com status IN ('agendada','reagendada'). Agora contamos só o evento de CRIAÇÃO da call
// (to_status = 'grupo_criado'), não importando qual era o from_status.
// changed_at = data em que a call foi MARCADA no sistema (não confundir com dt_call,
// que é a data em que a reunião vai ACONTECER - ver seção "CALLS AGENDADOS" abaixo).
const callsMarcadasRows = $('Calls Marcadas - Ler Dados').all().map(i => i.json);

function contarCallsMarcadasPorPeriodo(dataInicio, dataFim) {
  // dataInicio inclusive, dataFim exclusive
  // Só conta calls cujo mailing_id existe na aba "mailing" (ou seja, vieram
  // de fato desse fluxo de campanha/SDR) - descarta calls de outras origens/pipelines.
  const porMidia = {};
  let total = 0;
  for (const r of callsMarcadasRows) {
    if (!r.changed_at) continue;
    if (!midiaPorMailingId.hasOwnProperty(String(r.mailing_id))) continue; // fora do escopo do mailing
    const dia = toDateOnly(r.changed_at);
    if (dia >= dataInicio && dia < dataFim) {
      total++;
      const midia = getMidia(r.mailing_id);
      const chave = midia !== null && midia !== undefined && !isNaN(midia) ? String(midia) : 'sem_midia';
      porMidia[chave] = (porMidia[chave] || 0) + 1;
    }
  }
  return { total, porMidia };
}

const resultOntemCallsMarcadas = contarCallsMarcadasPorPeriodo(ontem, hoje);
const result7dCallsMarcadas = contarCallsMarcadasPorPeriodo(inicio7d, hoje);

function formatarPorMidia(porMidia) {
  const entradas = Object.entries(porMidia).sort((a, b) => b[1] - a[1]);
  if (entradas.length === 0) return '(nenhuma call marcada nesse período)';
  return entradas.map(([codigo, qtd]) => `- ${nomeMidia(codigo === 'sem_midia' ? null : codigo)}: ${qtd}`).join('\n');
}

const callsCriadosOntem = resultOntemCallsMarcadas.total;
const callsCriados7d = result7dCallsMarcadas.total;
const reunioesMarcadasOntemTexto = formatarPorMidia(resultOntemCallsMarcadas.porMidia);
const reunioesMarcadas7dTexto = formatarPorMidia(result7dCallsMarcadas.porMidia);

// --- CALLS AGENDADOS PARA HOJE E PARA O FUTURO (via calls_pipeline.dt_call) ---
// dt_call = data em que a reunião VAI ACONTECER (diferente de changed_at acima, que é
// quando ela foi marcada). Contamos independente do status atual da call, conforme decidido
// (inclusive canceladas/remarcadas continuam contando pra esse número).
// Só conta calls cujo mailing_id existe na aba "mailing" - mesma regra de escopo
// aplicada acima para "calls marcadas", pra não misturar calls de outras origens/pipelines.
const callsAgendadasRows = $('Calls Agendadas - Ler Dados').all().map(i => i.json);
let callsHoje = 0;
let callsFuturos = 0;
for (const r of callsAgendadasRows) {
  if (!r.dt_call) continue;
  if (!midiaPorMailingId.hasOwnProperty(String(r.mailing_id))) continue; // fora do escopo do mailing
  const diaReuniao = toDateOnly(r.dt_call);
  if (diaReuniao.getTime() === hoje.getTime()) callsHoje++;
  if (diaReuniao >= hoje) callsFuturos++;
}

return [{
  json: {
    disparos_ontem_total: disparosOntemTotal,          // vem do sdr_eventos
    disparos_ontem_1: tiposDisparoOntemPorTipo['1'],    // vem do sdr_eventos
    disparos_ontem_2: tiposDisparoOntemPorTipo['2'],
    disparos_ontem_3: tiposDisparoOntemPorTipo['3'],
    disparos_ontem_outbound: tiposDisparoOntemPorTipo['outbound'],
    disparos_ontem_remarketing: disparosOntemRemarketing,
    disparos_ontem_inbound: disparosOntemInbound,
    disparos_7d_total: disparos7dTotal,                // vem do sdr_eventos
    disparos_7d_1: tiposDisparo7dPorTipo['1'],          // vem do sdr_eventos
    disparos_7d_2: tiposDisparo7dPorTipo['2'],
    disparos_7d_3: tiposDisparo7dPorTipo['3'],
    disparos_7d_outbound: tiposDisparo7dPorTipo['outbound'],
    disparos_7d_remarketing: disparos7dRemarketing,
    disparos_7d_inbound: disparos7dInbound,
    respostas_hoje: respostasHoje,
    respostas_ontem: respostasOntem,
    respostas_7d: respostas7d,
    respostas_tipo_hoje_1: respostasTipoHoje['1'],
    respostas_tipo_hoje_2: respostasTipoHoje['2'],
    respostas_tipo_hoje_3: respostasTipoHoje['3'],
    respostas_tipo_hoje_outbound: respostasTipoHoje['outbound'],
    respostas_sem_disparo_hoje: respostasSemDisparoHoje,
    respostas_hoje_remarketing: respostasHojeRemarketing,
    respostas_hoje_inbound: respostasHojeInbound,
    respostas_tipo_7d_1: respostasTipo7d['1'],
    respostas_tipo_7d_2: respostasTipo7d['2'],
    respostas_tipo_7d_3: respostasTipo7d['3'],
    respostas_tipo_7d_outbound: respostasTipo7d['outbound'],
    respostas_sem_disparo_7d: respostasSemDisparo7d,
    respostas_7d_remarketing: respostas7dRemarketing,
    respostas_7d_inbound: respostas7dInbound,
    taxa_resposta_ontem: taxaRespostaOntem.toFixed(1),
    taxa_resposta_7d: taxaResposta7d.toFixed(1),
    calls_criados_ontem: callsCriadosOntem,
    calls_criados_7d: callsCriados7d,
    calls_hoje: callsHoje,
    calls_futuros_agendados: callsFuturos,
    reunioes_marcadas_ontem_texto: reunioesMarcadasOntemTexto,
    reunioes_marcadas_7d_texto: reunioesMarcadas7dTexto
  }
}];
